fn check_header(source: &str, expected_stdout: &str, expected_stderr: &str) {
    let directory = CaseDirectory::new();
    std::fs::write(directory.0.join("header.mori"), source).expect("write source");
    let json = Command::new(env!("CARGO_BIN_EXE_mori"))
        .current_dir(&directory.0)
        .args(["--color", "never", "check", "header.mori", "--json"])
        .output()
        .expect("run public JSON check");
    assert_eq!(json.status.code(), Some(1), "source:\n{source}");
    assert_eq!(json.stdout, expected_stdout.as_bytes(), "source:\n{source}");
    assert!(
        json.stderr.is_empty(),
        "source:\n{source}: {:?}",
        json.stderr
    );

    let human = Command::new(env!("CARGO_BIN_EXE_mori"))
        .current_dir(&directory.0)
        .args(["--color", "never", "--quiet", "check", "header.mori"])
        .output()
        .expect("run public quiet human check");
    assert_eq!(human.status.code(), Some(1), "source:\n{source}");
    assert!(human.stdout.is_empty(), "source:\n{source}");
    assert_eq!(
        human.stderr,
        expected_stderr.as_bytes(),
        "source:\n{source}"
    );

    let normal = Command::new(env!("CARGO_BIN_EXE_mori"))
        .current_dir(&directory.0)
        .args(["--color", "never", "check", "header.mori"])
        .output()
        .expect("run public human check");
    assert_eq!(normal.status.code(), Some(1), "source:\n{source}");
    assert!(normal.stdout.is_empty(), "source:\n{source}");
    let normal_stderr = format!("    Checking header.mori\n{expected_stderr}");
    assert_eq!(normal.stderr, normal_stderr.as_bytes(), "source:\n{source}");
}

#[test]
fn source_only_inspect_keeps_complete_header_errors() {
    let project = Project::new();
    // Capture each public process stream before assertions, including on failure.
    let captured = CASES
        .iter()
        .map(|case| {
            let error = mori_core::language(case.source)
                .err()
                .map(|error| serde_json::to_value(error).unwrap())
                .unwrap_or(Value::Null);
            let output = project.run(case.name, case.source);
            fs::write(
                project.root.join(case.name).join("producer-error.json"),
                serde_json::to_vec_pretty(&error).unwrap(),
            )
            .unwrap();
            (case, error, output)
        })
        .collect::<Vec<_>>();
    for (case, error, output) in captured {
        let expected: Value = serde_json::from_str(case.expected_error).unwrap();
        assert_eq!(error, expected, "{}: complete producer Error", case.name);
        assert_eq!(output.status.code(), Some(1), "{}", case.name);
        assert!(output.stdout.is_empty(), "{}: complete stdout", case.name);
        assert_eq!(
            output.stderr,
            case.expected_stderr.as_bytes(),
            "{}: complete human stream",
            case.name
        );
    }
}

    let empty = project.run("empty-core2", EMPTY_CORE2);
    for (case, error, output) in captured {
        let expected: Value = serde_json::from_str(case.expected_error).unwrap();
        assert_eq!(
            error, expected,
            "{}: complete producer Error, including UTF-8 offset",
            case.name
        );
        assert_eq!(output.status.code(), Some(1), "{}", case.name);
        assert!(output.stdout.is_empty(), "{}", case.name);
        assert_eq!(
            output.stderr,
            case.expected_stderr.as_bytes(),
            "{}: complete human stream",
            case.name
        );
    }
    assert_eq!(empty.status.code(), Some(0));
    assert!(empty.stderr.is_empty());
    let report: Value = serde_json::from_slice(&empty.stdout).unwrap();
    assert_eq!(report["status"], "complete");
    assert_eq!(
        report["segment"]["execution"],
        serde_json::from_str::<Value>(EMPTY_EXECUTION).unwrap()
    );
}
